        DESCRIPTIONS.add("Wander between points on the hitbox instead of locking the centre", "\u0411\u043b\u0443\u0436\u0434\u0430\u0442\u044c \u043c\u0435\u0436\u0434\u0443 \u0442\u043e\u0447\u043a\u0430\u043c\u0438 \u043d\u0430 \u0445\u0438\u0442\u0431\u043e\u043a\u0441\u0435 \u0432\u043c\u0435\u0441\u0442\u043e \u0444\u0438\u043a\u0441\u0430\u0446\u0438\u0438 \u0446\u0435\u043d\u0442\u0440\u0430");
        DESCRIPTIONS.add("Reaction delay, noise and humanised easing", "\u0417\u0430\u0434\u0435\u0440\u0436\u043a\u0430 \u0440\u0435\u0430\u043a\u0446\u0438\u0438, \u0448\u0443\u043c \u0438 \u0447\u0435\u043b\u043e\u0432\u0435\u0447\u0435\u0441\u043a\u0430\u044f \u043f\u043b\u0430\u0432\u043d\u043e\u0441\u0442\u044c");
        DESCRIPTIONS.add("Trigger bypass mode: Shard / Shard 2.0 add silent rotation and a reach guard", "\u0420\u0435\u0436\u0438\u043c \u043e\u0431\u0445\u043e\u0434\u0430 \u0442\u0440\u0438\u0433\u0433\u0435\u0440\u0430: Shard / Shard 2.0 \u0434\u043e\u0431\u0430\u0432\u043b\u044f\u044e\u0442 \u0442\u0438\u0445\u0438\u0439 \u043f\u043e\u0432\u043e\u0440\u043e\u0442 \u0438 \u0437\u0430\u0449\u0438\u0442\u0443 \u0434\u0438\u0441\u0442\u0430\u043d\u0446\u0438\u0438");
        DESCRIPTIONS.add("How far to look for a target (attacks stay inside the server limit)", "\u041d\u0430 \u043a\u0430\u043a\u043e\u0439 \u0434\u0438\u0441\u0442\u0430\u043d\u0446\u0438\u0438 \u0438\u0441\u043a\u0430\u0442\u044c \u0446\u0435\u043b\u044c (\u0443\u0434\u0430\u0440\u044b \u043e\u0441\u0442\u0430\u044e\u0442\u0441\u044f \u0432 \u043f\u0440\u0435\u0434\u0435\u043b\u0430\u0445 \u0441\u0435\u0440\u0432\u0435\u0440\u0430)");
        DESCRIPTIONS.add("How close to the crosshair a target must be for silent trigger", "\u041d\u0430\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0431\u043b\u0438\u0437\u043a\u043e \u0446\u0435\u043b\u044c \u0434\u043e\u043b\u0436\u043d\u0430 \u0431\u044b\u0442\u044c \u043a \u043f\u0440\u0438\u0446\u0435\u043b\u0443 \u0434\u043b\u044f \u0442\u0438\u0445\u043e\u0433\u043e \u0442\u0440\u0438\u0433\u0433\u0435\u0440\u0430");
        DESCRIPTIONS.add("Human reaction delay before the first hit on a new target", "\u0427\u0435\u043b\u043e\u0432\u0435\u0447\u0435\u0441\u043a\u0430\u044f \u0437\u0430\u0434\u0435\u0440\u0436\u043a\u0430 \u0440\u0435\u0430\u043a\u0446\u0438\u0438 \u043f\u0435\u0440\u0435\u0434 \u043f\u0435\u0440\u0432\u044b\u043c \u0443\u0434\u0430\u0440\u043e\u043c \u043f\u043e \u043d\u043e\u0432\u043e\u0439 \u0446\u0435\u043b\u0438");
        DESCRIPTIONS.add("Keeps the expanded box inside the reach the server accepts (Shard / Shard 2.0)", "\u0414\u0435\u0440\u0436\u0438\u0442 \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u043d\u044b\u0439 \u0445\u0438\u0442\u0431\u043e\u043a\u0441 \u0432 \u043f\u0440\u0435\u0434\u0435\u043b\u0430\u0445 \u0434\u0438\u0441\u0442\u0430\u043d\u0446\u0438\u0438, \u043a\u043e\u0442\u043e\u0440\u0443\u044e \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u0442 \u0441\u0435\u0440\u0432\u0435\u0440 (Shard / Shard 2.0)");
        DESCRIPTIONS.add("Maximum real attack distance while the box is expanded", "\u041c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u044c\u043d\u0430\u044f \u0440\u0435\u0430\u043b\u044c\u043d\u0430\u044f \u0434\u0438\u0441\u0442\u0430\u043d\u0446\u0438\u044f \u0443\u0434\u0430\u0440\u0430 \u043f\u0440\u0438 \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u043d\u043e\u043c \u0445\u0438\u0442\u0431\u043e\u043a\u0441\u0435");
        DESCRIPTIONS.add("Aim through blocks", "\u041d\u0430\u0432\u043e\u0434\u0438\u0442\u044c\u0441\u044f \u0447\u0435\u0440\u0435\u0437 \u0431\u043b\u043e\u043a\u0438");
        DESCRIPTIONS.add("Allow block placement attempts through walls", "\u0420\u0430\u0437\u0440\u0435\u0448\u0430\u0435\u0442 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0443 \u0431\u043b\u043e\u043a\u043e\u0432 \u0447\u0435\u0440\u0435\u0437 \u0441\u0442\u0435\u043d\u044b");
