        DESCRIPTIONS.add("Color of the cosmetic model", "\u0426\u0432\u0435\u0442 \u043a\u043e\u0441\u043c\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u043c\u043e\u0434\u0435\u043b\u0438");
