        DESCRIPTIONS.add("Item scroller delay", "\u0417\u0430\u0434\u0435\u0440\u0436\u043a\u0430 \u043f\u0440\u043e\u043a\u0440\u0443\u0442\u043a\u0438 \u043f\u0440\u0435\u0434\u043c\u0435\u0442\u043e\u0432");
        DESCRIPTIONS.add("Jump after using wind charge", "\u041f\u0440\u044b\u0433\u0430\u0442\u044c \u043f\u043e\u0441\u043b\u0435 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u044f \u0437\u0430\u0440\u044f\u0434\u0430 \u0432\u0435\u0442\u0440\u0430");
        DESCRIPTIONS.add("Jump only while Attack Aura has a target", "\u041f\u0440\u044b\u0433\u0430\u0442\u044c \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u0438 \u043d\u0430\u043b\u0438\u0447\u0438\u0438 \u0446\u0435\u043b\u0438 Attack Aura");
        DESCRIPTIONS.add("Keep sprinting while affected by blindness", "\u0421\u043e\u0445\u0440\u0430\u043d\u044f\u0442\u044c \u0441\u043f\u0440\u0438\u043d\u0442 \u043f\u0440\u0438 \u0441\u043b\u0435\u043f\u043e\u0442\u0435");
        DESCRIPTIONS.add("Length of firefly trail in ticks", "\u0414\u043b\u0438\u043d\u0430 \u0441\u043b\u0435\u0434\u0430 \u0441\u0432\u0435\u0442\u043b\u044f\u0447\u043a\u043e\u0432 \u0432 \u0442\u0438\u043a\u0430\u0445");
        DESCRIPTIONS.add("Length of the cosmetic model", "\u0414\u043b\u0438\u043d\u0430 \u043a\u043e\u0441\u043c\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u043c\u043e\u0434\u0435\u043b\u0438");
        DESCRIPTIONS.add("Light dispersion size from hands", "\u0420\u0430\u0437\u043c\u0435\u0440 \u0440\u0430\u0441\u0441\u0435\u0438\u0432\u0430\u043d\u0438\u044f \u0441\u0432\u0435\u0442\u0430 \u043e\u0442 \u0440\u0443\u043a");
        DESCRIPTIONS.add("Lightning color source", "\u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u0446\u0432\u0435\u0442\u0430 \u043c\u043e\u043b\u043d\u0438\u0439");
        DESCRIPTIONS.add("Liquid glass effect settings", "\u041d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0438 \u0436\u0438\u0434\u043a\u043e\u0433\u043e \u0441\u0442\u0435\u043a\u043b\u0430");
        DESCRIPTIONS.add("Lower damage threshold below this health", "\u0421\u043d\u0438\u0437\u0438\u0442\u044c \u043f\u043e\u0440\u043e\u0433 \u0443\u0440\u043e\u043d\u0430 \u043f\u0440\u0438 \u0442\u0430\u043a\u043e\u043c \u0437\u0434\u043e\u0440\u043e\u0432\u044c\u0435 \u0446\u0435\u043b\u0438");
        DESCRIPTIONS.add("Main color of the effect", "\u041e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u0446\u0432\u0435\u0442 \u044d\u0444\u0444\u0435\u043a\u0442\u0430");
        DESCRIPTIONS.add("Matrix strafe speed", "\u0421\u043a\u043e\u0440\u043e\u0441\u0442\u044c \u0441\u0442\u0440\u0435\u0439\u0444\u0430 Matrix");
