        DESCRIPTIONS.add("Maximum accepted self damage", "\u041c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u044c\u043d\u043e \u0434\u043e\u043f\u0443\u0441\u0442\u0438\u043c\u044b\u0439 \u0443\u0440\u043e\u043d \u0441\u0435\u0431\u0435");
        DESCRIPTIONS.add("Maximum allowed self damage", "\u041c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u044c\u043d\u043e \u0434\u043e\u043f\u0443\u0441\u0442\u0438\u043c\u044b\u0439 \u0443\u0440\u043e\u043d \u043f\u043e \u0441\u0435\u0431\u0435");
        DESCRIPTIONS.add("Maximum crystal attack range", "\u041c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u044c\u043d\u0430\u044f \u0434\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u0432\u0437\u0440\u044b\u0432\u0430 \u043a\u0440\u0438\u0441\u0442\u0430\u043b\u043b\u043e\u0432");
        DESCRIPTIONS.add("Maximum crystal placement range", "\u041c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u044c\u043d\u0430\u044f \u0434\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0438 \u043a\u0440\u0438\u0441\u0442\u0430\u043b\u043b\u043e\u0432");
        DESCRIPTIONS.add("Maximum distance for Network links", "\u041c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u044c\u043d\u0430\u044f \u0434\u043b\u0438\u043d\u0430 \u0441\u0432\u044f\u0437\u0435\u0439 \u0447\u0430\u0441\u0442\u0438\u0446");
        DESCRIPTIONS.add("Maximum forward speed in blocks per tick", "\u041c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u044c\u043d\u0430\u044f \u0441\u043a\u043e\u0440\u043e\u0441\u0442\u044c \u0432\u043f\u0435\u0440\u0451\u0434 \u0432 \u0431\u043b\u043e\u043a\u0430\u0445 \u0437\u0430 \u0442\u0438\u043a");
        DESCRIPTIONS.add("Maximum jump circle size", "\u041c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u044c\u043d\u044b\u0439 \u0440\u0430\u0437\u043c\u0435\u0440 \u043a\u0440\u0443\u0433\u0430 \u043f\u0440\u044b\u0436\u043a\u0430");
        DESCRIPTIONS.add("Maximum links per particle", "\u041c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u044c\u043d\u043e\u0435 \u043a\u043e\u043b\u0438\u0447\u0435\u0441\u0442\u0432\u043e \u0441\u0432\u044f\u0437\u0435\u0439 \u043d\u0430 \u0447\u0430\u0441\u0442\u0438\u0446\u0443");
        DESCRIPTIONS.add("Minimum CPS in 1.8 mode", "\u041c\u0438\u043d\u0438\u043c\u0443\u043c \u0443\u0434\u0430\u0440\u043e\u0432 \u0432 \u0441\u0435\u043a\u0443\u043d\u0434\u0443 \u0432 \u0440\u0435\u0436\u0438\u043c\u0435 1.8");
        DESCRIPTIONS.add("Minimum damage to the target", "\u041c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043d\u044b\u0439 \u0443\u0440\u043e\u043d \u0446\u0435\u043b\u0438");
