        DESCRIPTIONS.add("Minimum target damage for an explosion", "\u041c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043d\u044b\u0439 \u0443\u0440\u043e\u043d \u0446\u0435\u043b\u0438 \u043e\u0442 \u0432\u0437\u0440\u044b\u0432\u0430");
        DESCRIPTIONS.add("Move into a nearby safe hole while a target is close", "\u041f\u0435\u0440\u0435\u043c\u0435\u0449\u0430\u0442\u044c\u0441\u044f \u0432 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u0443\u044e \u044f\u043c\u0443 \u0440\u044f\u0434\u043e\u043c \u0441 \u0446\u0435\u043b\u044c\u044e");
