        DESCRIPTIONS.add("Nickname that will replace yours", "\u041d\u0438\u043a \u0434\u043b\u044f \u0437\u0430\u043c\u0435\u043d\u044b \u0432\u0430\u0448\u0435\u0433\u043e \u0438\u043c\u0435\u043d\u0438");
