        DESCRIPTIONS.add("Number of firefly particles", "\u041a\u043e\u043b\u0438\u0447\u0435\u0441\u0442\u0432\u043e \u0441\u0432\u0435\u0442\u043b\u044f\u0447\u043a\u043e\u0432");
