        DESCRIPTIONS.add("Number of regular particles", "\u041a\u043e\u043b\u0438\u0447\u0435\u0441\u0442\u0432\u043e \u043e\u0431\u044b\u0447\u043d\u044b\u0445 \u0447\u0430\u0441\u0442\u0438\u0446");
