        DESCRIPTIONS.add("Particle source settings", "\u041d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0438 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u043e\u0432 \u0447\u0430\u0441\u0442\u0438\u0446");
