        DESCRIPTIONS.add("Quality of the blur (higher = smoother but slower)", "\u041a\u0430\u0447\u0435\u0441\u0442\u0432\u043e \u0440\u0430\u0437\u043c\u044b\u0442\u0438\u044f: \u0432\u044b\u0448\u0435 \u2014 \u043f\u043b\u0430\u0432\u043d\u0435\u0435, \u043d\u043e \u043c\u0435\u0434\u043b\u0435\u043d\u043d\u0435\u0435");
