        DESCRIPTIONS.add("Render the hat on friends too", "\u041f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0442\u044c \u0448\u043b\u044f\u043f\u0443 \u0438 \u043d\u0430 \u0434\u0440\u0443\u0437\u044c\u044f\u0445");
