        DESCRIPTIONS.add("Second custom theme color", "\u0412\u0442\u043e\u0440\u043e\u0439 \u0446\u0432\u0435\u0442 \u0441\u0432\u043e\u0435\u0439 \u0442\u0435\u043c\u044b");
