    private static final class Dictionary {
        private final Map<String, String> russian = new HashMap<String, String>();
        private final Map<String, String> english = new HashMap<String, String>();

        private Dictionary() {
        }

        private void add(String en, String ru) {
            this.russian.putIfAbsent(en, ru);
            this.english.putIfAbsent(ru, en);
        }

        private String get(String value) {
            return (MenuDescriptionLocalizer.isRussian() ? this.russian : this.english).get(value);
        }
    }
